function chaseDirection(a,b){const direct=v3(b.pos.x-a.pos.x,0,b.pos.z-a.pos.z);if(direct.lengthSq()<.00001)return direct;if(!worldColliders.length||navigationLineClear(a.pos.x,a.pos.z,b.pos.x,b.pos.z,.50)){a.navPlan=null;return direct.normalize();}let plan=a.navPlan;const moved=plan?Math.hypot(plan.target.x-b.pos.x,plan.target.z-b.pos.z):Infinity;let replan=!plan||plan.source!==worldColliders||(time>plan.next&&moved>.8);if(plan&&time>plan.checkAt){if(Math.hypot(plan.last.x-a.pos.x,plan.last.z-a.pos.z)<.10)replan=true;plan.checkAt=time+.75;plan.last.copy(a.pos);}if(replan){plan=a.navPlan={source:worldColliders,target:b.pos.clone(),points:planNavigation(a,b),index:0,next:time+.55,checkAt:time+.75,last:a.pos.clone()};}while(plan.index<plan.points.length&&Math.hypot(plan.points[plan.index].x-a.pos.x,plan.points[plan.index].z-a.pos.z)<.22)plan.index++;if(plan.index>=plan.points.length)return v3();const point=plan.points[plan.index];return v3(point.x-a.pos.x,0,point.z-a.pos.z).normalize();}
function separateBodies(){const minimum=hero.radius+rival.radius+.00005;for(let pass=0;pass<3;pass++){for(let i=0;i<4;i++){const d=v3(hero.pos.x-rival.pos.x,0,hero.pos.z-rival.pos.z),length=d.length();if(length>=minimum-.00001)break;if(length<.00001)d.set(-1,0,0);else d.divideScalar(length);const correction=(minimum-length)*.5;hero.pos.addScaledVector(d,correction);rival.pos.addScaledVector(d,-correction);clampArena(hero.pos);clampArena(rival.pos);}if(distance(hero,rival)<minimum-.00001){const normal=v3(hero.pos.x-rival.pos.x,0,hero.pos.z-rival.pos.z).normalize();if(normal.lengthSq()<.001)normal.set(-1,0,0);const h=rival.pos.clone().addScaledVector(normal,minimum),r=hero.pos.clone().addScaledVector(normal,-minimum);h.y=hero.pos.y;r.y=rival.pos.y;if(insideArena(h))hero.pos.copy(h);else if(insideArena(r))rival.pos.copy(r);else{const y=hero.pos.y,inward=v3(-rival.pos.x,0,-7-rival.pos.z).normalize();if(inward.lengthSq()<.001)inward.set(-1,0,0);hero.pos.copy(rival.pos).addScaledVector(inward,minimum);hero.pos.y=y;}}resolveWorldBody(hero);resolveWorldBody(rival);if(distance(hero,rival)>=minimum-.00001)return;}}
function inkRing(a){const ring=energyRibbons([{radius:2.75,width:.045,start:-Math.PI,span:TAU,color:'#b4e1e4',alpha:.7},{radius:2.61,width:.016,start:-2.5,span:4.9,color:'#e5f7f5',alpha:.8},{radius:2.0,width:.13,start:-1.4,span:2.6,color:'#609097',alpha:.22},{radius:2.4,width:.055,start:.8,span:3.3,color:'#7bbcc5',alpha:.4}]);ring.position.copy(a.pos);ring.position.y=.055;scene.add(ring);trails.push({mesh:ring,life:.48,max:.48,expand:.5});waterRipple(a.pos,2.45,.65);}
function burst(pos,color='#c1e5eb',count=18){if(prefersReduced.matches)count=Math.ceil(count*.5);const rgb=new THREE.Color(color);for(let i=0;i<count&&particles.length<SPARK_LIMIT;i++){const life=.18+Math.random()*.28;particles.push({position:pos.clone(),velocity:v3((Math.random()-.5)*5.5,Math.random()*3.5,(Math.random()-.5)*5.5),color:rgb,life,max:life,streak:i%3!==0});}}
function qiMote(p){if(particles.length>=SPARK_LIMIT)return;const life=.18+Math.random()*.16;particles.push({position:p.position.clone().add(v3((Math.random()-.5)*1.35,(Math.random()-.5)*.45,0)),velocity:p.direction.clone().multiplyScalar(-2).add(v3(0,.3,0)),color:new THREE.Color('#8bd9e1'),life,max:life,streak:false});}
function spinProgress(a){const p=clamp((1-a.specialTime/a.specialMax-.18)/.60,0,1);return p*p*(3-2*p);}
