function frame(stamp){try{const frameBegin=globalThis.performance?.now?.()??0;let raw=last?Math.max(0,(stamp-last)/1000):0;last=stamp;if(raw>.5&&status==='playing'){pause();say('画面短暂中断，已暂停。继续后再战。');raw=0;}if(status==='playing'&&!document.hidden){simulationAccumulator+=Math.min(raw,.5);let steps=0;while(simulationAccumulator>=1/60&&steps<32){updateCombat(1/60);simulationAccumulator-=1/60;steps++;}}else simulationAccumulator=0;recordTiming('simulationMs',(globalThis.performance?.now?.()??frameBegin)-frameBegin);updateVisual(Math.min(raw,.25));recordTiming('totalMs',(globalThis.performance?.now?.()??frameBegin)-frameBegin);if(!performanceStart){performanceStart=stamp;performanceFrames=0;}else performanceFrames++;if(stamp-performanceStart>=1000){performanceWindowMs=Math.round(stamp-performanceStart);measuredFPS=Math.round(performanceFrames*1000/(stamp-performanceStart));if(ready&&!document.hidden&&status!=='paused'&&qualityMode==='auto'){lowFPSWindows=measuredFPS<42?lowFPSWindows+1:0;highFPSWindows=measuredFPS>55?highFPSWindows+1:0;const ratio=renderer.getPixelRatio();if(lowFPSWindows>=3&&ratio>.75){renderer.setPixelRatio(Math.max(.75,Math.round((ratio-.15)*100)/100));resize();lowFPSWindows=0;}else if(highFPSWindows>=8&&ratio<Math.min(1.25,devicePixelRatio)){renderer.setPixelRatio(Math.min(devicePixelRatio,1.25,Math.round((ratio+.1)*100)/100));resize();highFPSWindows=0;}}performanceFrames=0;performanceStart=stamp;}requestAnimationFrame(frame);}catch(error){fatalRenderError=true;ready=false;status='paused';clearInput();loadMessage('3D画面运行中断，对决已停止。请刷新页面重新载入。',0,true);console.error('3D frame failed:',error);}}
window.addEventListener('keydown',e=>{if(e.defaultPrevented||e.target&&(/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable||(e.code==='Space'&&/^(BUTTON|A)$/.test(e.target.tagName))))return;if(cameraKeyMap[e.code]&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();if(!cameraKeys.has(e.code))nudgeCamera(cameraKeyMap[e.code],.055);cameraKeys.add(e.code);return;}if(e.code==='Tab'&&status==='playing'&&!/^(BUTTON|A)$/.test(e.target?.tagName??'')){e.preventDefault();if(!e.repeat)action('lock');return;}if(e.code==='Escape'){e.preventDefault();if(!e.repeat)pause();return;}const a=keyMap[e.code];if(a&&status==='playing'){e.preventDefault();if(!keys.has(e.code)){keys.add(e.code);action(a,true);}}});
window.addEventListener('keyup',e=>{cameraKeys.delete(e.code);keys.delete(e.code);const a=keyMap[e.code];if(a)action(a,false);});
window.addEventListener('blur',()=>{clearInput();if(status==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(status==='playing')pause();}});
try{hero=actor('hero');rival=actor('rival');actors.push(hero,rival);initScene();loadWorld();loadMessage('雨夜已至 · 正在载入两位侠客',.25);requestAnimationFrame(frame);loadActors().catch(error=>{ready=false;status='menu';loadMessage('人物或兵刃载入失败。请检查网络后刷新页面；未使用占位模型冒充成品。',0,true);console.error('Character model loading failed:',error);});}catch(error){ready=false;status='menu';loadMessage('当前浏览器未能建立 3D 画面。请使用支持 WebGL 的最新版浏览器重新打开。',0,true);console.error('3D initialization failed:',error);}
